import {PLAYER_ARTWORK} from './artwork-data.js';
import {playerAppearance} from './presentation.js';
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sectionCard(kicker,title,body,classes=''){return `<section class="card studio-card ${classes}"><header><span class="eyebrow">${escapeHtml(kicker)}</span><h2>${escapeHtml(title)}</h2></header>${body}</section>`;}
export function metric(label,value,note=''){return `<div class="studio-metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong>${note?`<small>${escapeHtml(note)}</small>`:''}</div>`;}
export function clubBadge(name,color='#b6f36a'){return `<span class="studio-badge" style="--club:${/^#[0-9a-f]+$/i.test(color)?color:'#b6f36a'}" aria-hidden="true">${escapeHtml(name.split(' ').map(n=>n[0]).slice(0,3).join(''))}<i>FC</i></span>`;}
export function panelTabs(id,panels,selected){const current=panels.some(p=>p.id===selected)?selected:panels[0]?.id;return `<section class="studio-panels" data-panel-group="${id}"><nav role="tablist" aria-label="Competition views">${panels.map(p=>`<button class="btn secondary" id="${id}-tab-${p.id}" role="tab" aria-controls="${id}-${p.id}" aria-selected="${p.id===current}" tabindex="${p.id===current?0:-1}" data-panel-target="${p.id}">${escapeHtml(p.name)}</button>`).join('')}</nav>${panels.map(p=>`<div id="${id}-${p.id}" role="tabpanel" aria-labelledby="${id}-tab-${p.id}" data-panel="${p.id}" ${p.id===current?'':'hidden'}>${p.html}</div>`).join('')}</section>`;}
export function dealProgress(stage){const steps=['club','contract','ready','complete'],index=stage==='pending'?2:steps.indexOf(stage);return `<ol class="deal-progress" aria-label="Negotiation progress">${['Club terms','Player terms','Confirmation','Registered'].map((name,i)=>`<li class="${i<index?'done':i===index?'current':''}" ${i===index?'aria-current="step"':''}><span>${i+1}</span>${name}</li>`).join('')}</ol>`;}
export function portraitArtwork(player={}){const file=PLAYER_ARTWORK[player.id]||PLAYER_ARTWORK[player.profileId];return file?`<img class="player-artwork" src="./assets/library/players/${encodeURIComponent(file)}" alt="Stylized artwork of ${escapeHtml(player.name||'player')}" loading="lazy" decoding="async">`:fallbackPortrait(player);}
function fallbackPortrait(player={}){const a=playerAppearance(player),color=/^#[0-9a-f]+$/i.test(player.color||'')?player.color:'#6d94b8',id='portrait-'+a.hash;return `<svg class="chapter-portrait studio-portrait" viewBox="0 0 240 280" role="img" aria-label="Original stylized player portrait"><defs><linearGradient id="${id}-bg" x2="1" y2="1"><stop stop-color="${color}"/><stop offset="1" stop-color="#101d30"/></linearGradient><linearGradient id="${id}-skin"><stop stop-color="${a.skin}"/><stop offset="1" stop-color="${a.skin}" stop-opacity=".72"/></linearGradient></defs><rect width="240" height="280" rx="14" fill="url(#${id}-bg)"/><path d="m170 0-70 280M210 0l-70 280M250 0l-70 280" stroke="#d3e6f9" stroke-width="20" opacity=".045"/><ellipse cx="120" cy="276" rx="105" ry="13" fill="#05101d" opacity=".3"/><path d="M20 280v-53q5-33 73-50h54q68 17 73 50v53" fill="${color}"/><path d="m87 179 33 25 33-25-10-27H97z" fill="${a.skin}"/><path d="m99 153 39 4-2 25-16 12-21-19z" fill="#30231e" opacity=".19"/><path d="M78 81q-5-45 42-45 45 0 42 45v31q-7 54-42 54-34 0-42-54z" fill="url(#${id}-skin)"/><path d="M77 96q-9-62 35-67 51-5 54 51l-10 21-9-38q-21 15-55 5l-8 31z" fill="${a.hair}"/><path d="m91 101 16-3m27 0 15 3" stroke="${a.hair}" stroke-width="4" stroke-linecap="round"/><circle cx="101" cy="109" r="2.2" fill="#26313a"/><circle cx="140" cy="109" r="2.2" fill="#26313a"/><path d="m119 108-4 19h10m-18 15q13 5 26-1" fill="none" stroke="#644134" stroke-opacity=".6" stroke-width="2.5" stroke-linecap="round"/><path d="m87 180 33 24 33-24" fill="none" stroke="#e4ecf1" stroke-opacity=".85" stroke-width="5"/><path d="m61 197-8 77m126-77 8 77" stroke="#0c1927" stroke-opacity=".24" stroke-width="4"/><path d="M39 213h22m118 0h22" stroke="#e6eef5" stroke-width="4" opacity=".7"/><text x="120" y="262" text-anchor="middle" fill="#f0f6fb" font-size="39" font-family="sans-serif" font-weight="800" opacity=".85">${player.role==='GK'?'1':'10'}</text></svg>`;}
